import context7Ask from "./context7-ask.json";

/**
 * Context7 Ask — search endpoint for mohr-more.biz.
 *
 * The site key and endpoint base URL live in `context7-ask.json`, the one
 * place they are defined. Everything that exposes the endpoint derives from
 * these constants:
 *
 *   - the `context7-site-verification` meta tag and the hidden note rendered
 *     by `src/components/context7-ask.tsx` in both root layouts,
 *   - the `Link` response header in `public/_headers`, generated by
 *     `scripts/context7-ask-headers.mjs` from the same JSON file.
 */
export const CONTEXT7_ASK_SITE_KEY = context7Ask.siteKey;

export const CONTEXT7_ASK_ENDPOINT = `${context7Ask.baseUrl}?siteKey=${context7Ask.siteKey}`;
